import json
import re
from execution_context import Context

SEV = {"critical": "SEV-1", "high": "SEV-2", "medium": "SEV-3", "low": "SEV-4", "informational": "SEV-5"}
STATE = {"open": "active", "closed": "resolved"}
# Attributes that change on every version; ignored in Last Change.
VOLATILE = re.compile(
    r"^(last_modified|event_time|trigger_time|timestamp|date|cyberhaven\.message"
    r"|cyberhaven\.incident\.last_modified|.*\.(timestamp|ingestion_timestamp))$"
)
# (incident field, log attribute) copied as-is into textbox fields.
PLAIN_FIELDS = [
    ("tenant", "cyberhaven.domain"), ("policy_name", "policy.name"), ("cyberhaven_created_by", "created_by"),
    ("dataset_name", "dataset.name"), ("risk_score", "risk_score"), ("blocked", "blocked"), ("user_id", "usr.id"),
    ("warning_status", "warning_status"), ("event_time", "event_time"), ("trigger_time", "trigger_time"),
    ("resolution_time", "resolution_time"), ("close_reason", "close_reason"), ("close_note", "close_note"),
    ("cyberhaven_ai_summary", "ai_summary"), ("policy_id", "policy.id"), ("dataset_id", "dataset.id"),
]
# (incident field, action.* attribute) from end_event, falling back to start_event.
ACTION_FIELDS = [
    ("hostname", "hostname"), ("device_type", "device_type"), ("sensor_kind", "sensor_kind"),
    ("client_ip", "ip_address"), ("data_size_bytes", "data_size"),
]


def dig(src, path, default=None):
    for part in path.split("."):
        if isinstance(src, dict) and src.get(part) is not None:
            src = src[part]
        else:
            return default
    return src


def to_text(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    if isinstance(v, (dict, list)):
        return json.dumps(v, ensure_ascii=False)
    return str(v)


def flatten(v, prefix, flat):
    if isinstance(v, list):
        for i, item in enumerate(v):
            flatten(item, prefix + "[" + str(i) + "]", flat)
    elif isinstance(v, dict):
        for k, item in v.items():
            flatten(item, prefix + "." + k if prefix else k, flat)
    elif prefix:
        flat[prefix] = v
    return flat


def sort_key(lm):
    s, _, f = lm.rstrip("Z").partition(".")
    return s + "." + f.ljust(9, "0")


def main(*, ctx: Context):
    steps = ctx["Steps"]
    incident_id = dig(steps, "Parse_group.data.id", "")
    logs = dig(steps, "Get_log_details.data", []) or []
    if not logs:
        return {"found": False, "id": incident_id, "log_lines_found": 0}

    # One log line per incident version; newest last_modified first.
    versions = []
    for log in logs:
        a = flatten(dig(log, "attributes.attributes", {}) or {}, "", {})
        versions.append({"a": a, "lm": to_text(a.get("last_modified") or "")})
    versions.sort(key=lambda x: sort_key(x["lm"]), reverse=True)
    attrs = versions[0]["a"]
    prev = versions[1]["a"] if len(versions) > 1 else None

    def attr(k, d=""):
        v = attrs.get(k)
        return d if v is None or v == "" else v

    def txt(k):
        return to_text(attr(k))

    def act(n):
        return attr("event_details.end_event.action." + n, attr("event_details.start_event.action." + n))

    policy_name = to_text(attr("policy.name", "Cyberhaven incident"))
    action_kind = to_text(attr("evt.name", act("kind") or "event"))
    user_name = to_text(attr("usr.name", attr("user.local_username", "unknown user")))
    raw_status = txt("status").lower()
    ch_status = to_text(
        attr("cyberhaven.incident.status", raw_status if raw_status in ("open", "closed") else "open")
    ).lower()
    policy_sev = txt("policy.severity").lower()
    severity = SEV.get(policy_sev, "UNKNOWN")
    dd_state = STATE.get(ch_status, "active")
    url = txt("cyberhaven.incident.url")

    # Title: keep action/user intact; shorten the policy name instead.
    tail = " - " + action_kind + " by " + user_name
    max_len = max(20, 100 - len(tail))
    short = policy_name[: max_len - 3] + "..." if len(policy_name) > max_len else policy_name
    title = short + tail

    summary = "\n".join(line for line in [
        to_text(attr("cyberhaven.incident.summary", "Policy: " + policy_name + " (severity " + policy_sev + ")")),
        "Action: " + action_kind + " | outcome=" + txt("evt.outcome") + " | blocked=" + txt("blocked")
        + " | risk_score=" + txt("risk_score"),
        "Status: " + ch_status + (" (" + txt("close_reason") + ")" if attr("close_reason") else ""),
        "Event time: " + txt("event_time") + " | Last modified: " + txt("last_modified"),
        "Cyberhaven: " + url if url else "",
    ] if line)

    # Diff against the previous version.
    changes = "First version seen (no earlier version in the last 7 days)"
    changed = []
    if prev:
        keys = [k for k in dict.fromkeys(list(attrs) + list(prev)) if not VOLATILE.match(k)]

        def cmp(vals, k):
            return to_text(vals[k]) if k in vals else "undefined"

        def sv(v):
            t = "(empty)" if v is None or v == "" else to_text(v)
            return t[:117] + "..." if len(t) > 120 else t

        changed = [k for k in keys if cmp(attrs, k) != cmp(prev, k)]
        changes = (
            "; ".join(k + ": " + sv(prev.get(k)) + " -> " + sv(attrs.get(k)) for k in changed)
            if changed else "No attribute changes (only timestamps)"
        )
    changes = ("[" + txt("last_modified") + "] " + changes)[:2000]

    def tf(v):
        return {"type": "textbox", "value": "" if v is None else to_text(v)}

    def dd(v):
        return {"type": "dropdown", "value": to_text(v)}

    # Field names must match setup_datadog_incident_type.py.
    fields = {
        "severity": dd(severity),
        "state": dd(dd_state),
        "summary": tf(summary),
        "detection_method": dd("monitor"),
        "source_incident_id": tf(incident_id),
        "cyberhaven_incident_url": tf(url),
        "policy_severity": tf(policy_sev),
        "ai_severity": tf(txt("ai_severity").lower()),
        "dataset_sensitivity": tf(txt("dataset.sensitivity").lower()),
        "user": tf(user_name),
        "action_kind": tf(action_kind),
        "cyberhaven_status": tf(ch_status),
        "last_change": tf(changes),
    }
    for name, key in PLAIN_FIELDS:
        fields[name] = tf(attr(key))
    for name, key in ACTION_FIELDS:
        fields[name] = tf(act(key))
    # The Incidents API rejects empty values.
    fields = {n: f for n, f in fields.items() if f["value"].strip()}

    rows = [
        "| `" + k + "` | " + to_text(v).replace("|", "/").replace("\n", " ")[:500] + " |"
        for k, v in attrs.items()
    ]
    note = (
        "## Cyberhaven incident `" + to_text(incident_id) + "`\n\n"
        + ("[Open in Cyberhaven](" + url + ")\n\n" if url else "")
        + "| Attribute | Value |\n|---|---|\n" + "\n".join(rows)
    )[:20000]

    return {
        "found": True,
        "id": incident_id,
        "title": title,
        "severity_label": severity,
        "dd_state": dd_state,
        "summary": summary,
        "note": note,
        "fields": fields,
        "last_change": changes,
        "changed_keys": changed,
        "versions_found": len(versions),
        "attribute_count": len(attrs),
        "log_lines_found": len(logs),
        "customer_impacted": False,
    }

from execution_context import Context


def dig(source, path, default=None):
    """Read a dotted path from nested dicts; return default when any part is missing."""
    for part in path.split("."):
        if isinstance(source, dict) and source.get(part) is not None:
            source = source[part]
        else:
            return default
    return source


def main(*, ctx: Context):
    steps = ctx["Steps"]
    cyberhaven_incident_id = dig(steps, "Extract_incident_fields.data.id", "")
    search_result = dig(steps, "Search_existing_incident.data", {}) or {}
    incidents = (
        dig(search_result, "data.attributes.incidents")
        or dig(search_result, "attributes.incidents")
        or dig(search_result, "incidents")
        or []
    )

    # The search query is already filtered on source_incident_id; verify the exact value anyway.
    def source_incident_id(incident):
        return dig(
            incident,
            "data.attributes.fields.source_incident_id.value",
            dig(incident, "attributes.fields.source_incident_id.value"),
        )

    match = next(
        (incident for incident in incidents if cyberhaven_incident_id and source_incident_id(incident) == cyberhaven_incident_id),
        None,
    )
    return {
        "exists": match is not None,
        "incident_id": (dig(match, "data.id") or dig(match, "id") or None) if match else None,
        "search_id": cyberhaven_incident_id,
        "matches_returned": len(incidents),
    }
